  "Interviewer: Why do you want this role?",
  "Candidate: I want this job because I like helping customer and I have good experience in support. I think I can add value to your team and grow my skill.",
  "Interviewer: What is your biggest weakness?",
  "Candidate: Sometimes I take longer time because I check details a lot, but I am working on organizing my time."
].join("\n");

return [{
  json: {
    body: {
      candidateId: "TEST-CANDIDATE-0001",
      sessionId: "TEST-SESSION-0001",
      messageCount: 10,
      fullTranscript: transcript,
      evaluation: {
        communicationSkills: 7,
        englishFluency: 6,
        confidenceLevel: 7
      },
      criteria: JSON.stringify(["Customer service experience", "Bilingual support"])
    }
  }
}];

