const WEIGHTS = { communication_skills: 20, professional_attitude: 18, english_fluency: 15, confidence_level: 12, relevant_experience_role_fit: 20, problem_solving: 10, computer_skills: 5 };
const RATING_FRACTION = { excellent: 1.0, good: 0.75, intermediate: 0.5, bad: 0.0 };
const T_ADVANCE = 55;
const T_CONSIDER = 30;
const PRIOR_KEYS = { communication_skills: 'communicationSkills', english_fluency: 'englishFluency', confidence_level: 'confidenceLevel' };
const CORE_DIMS = ['communication_skills', 'professional_attitude'];
const MIN_ASSESSED_WEIGHT = 60;
const LEVELS = ['bad', 'intermediate', 'good', 'excellent'];
function norm(s) { return String(s == null ? '' : s).trim().toLowerCase(); }
function titleCase(s) { const x = norm(s); return x ? x.charAt(0).toUpperCase() + x.slice(1) : x; }
function isNotAssessed(r) { const x = norm(r); return x === '' || x === 'not assessed' || x === 'notassessed' || x === 'n/a' || x === 'na' || x === 'none'; }
function levelIdx(r) { return LEVELS.indexOf(norm(r)); }
function hasEvidence(v) { if (Array.isArray(v)) return v.some((x) => String(x || '').trim()); return String(v == null ? '' : v).trim().length > 0; }
function toArray(v) { if (Array.isArray(v)) return v.filter((x) => String(x || '').trim()); const s = String(v == null ? '' : v).trim(); return s ? [s] : []; }
function priorToRating(n) { n = Number(n); if (!Number.isFinite(n)) return null; if (n >= 8) return 'Excellent'; if (n >= 6) return 'Good'; if (n >= 4) return 'Intermediate'; if (n >= 1) return 'Bad'; return null; }
function getAssessment(item) { const j = item.json || {}; if (j.output && typeof j.output === 'object') return j.output; if (j.competencies && typeof j.competencies === 'object') return j; const raw = j.text || j.response || j.data || ''; const m = String(raw).match(/\{[\s\S]*\}/); if (m) { try { return JSON.parse(m[0]); } catch (e) {} } return {}; }
function getPriors(item) { try { const b = $('Webhook').first().json.body || {}; if (b.evaluation) return b.evaluation; } catch (e) {} return (item.json && item.json.body && item.json.body.evaluation) || item.json.__priors || {}; }
function enforcePrior(key, node, priorVal) { const priorRating = priorToRating(priorVal); if (key === 'english_fluency' && priorRating === null) { return { rating: 'Not Assessed', note: 'english_not_tested' }; } if (priorRating === null) return { rating: node.rating, note: 'no_prior' }; if (node.assessed === false) { return { rating: priorRating, note: 'reverted_llm_notassessed' }; } let r = node.rating; if (isNotAssessed(r) || levelIdx(r) < 0) { return { rating: priorRating, note: 'reverted_invalid_or_na' }; } const li = levelIdx(r), pi = levelIdx(priorRating); if (li === pi) return { rating: priorRating, note: 'matches_prior' }; const justified = node.adjusted_from_prior === true && hasEvidence(node.evidence); if (Math.abs(li - pi) === 1 && justified) { return { rating: titleCase(r), note: 'override_accepted' }; } return { rating: priorRating, note: 'override_rejected' }; }
const out = [];
for (const item of $input.all()) {
  const a = getAssessment(item);
  const comp = a.competencies || {};
  const priors = getPriors(item);
  let earned = 0;
  let assessedMax = 0;
  const ratings = {};
  const evidence = {};
  const notAssessed = [];
  const overrides = {};
  let coreMissing = false;
  for (const [key, max] of Object.entries(WEIGHTS)) {
    const node = comp[key] || {};
    let rating = node.rating;
    if (PRIOR_KEYS[key]) { const res = enforcePrior(key, node, priors[PRIOR_KEYS[key]]); rating = res.rating; overrides[key] = res.note; } else if (node.assessed === false) { rating = 'Not Assessed'; }
    evidence[key] = toArray(node.evidence);
    if (isNotAssessed(rating) || !(norm(rating) in RATING_FRACTION)) { ratings[key] = 'Not Assessed'; notAssessed.push(key); if (CORE_DIMS.includes(key)) coreMissing = true; continue; }
    earned += RATING_FRACTION[norm(rating)] * max;
    assessedMax += max;
    ratings[key] = titleCase(rating);
  }
  let status = 'scored';
  let score = assessedMax > 0 ? Math.round((earned / assessedMax) * 100) : null;
  let recommendation;
  if (coreMissing || assessedMax < MIN_ASSESSED_WEIGHT) { status = 'insufficient_data'; recommendation = 'Consider'; } else { recommendation = score >= T_ADVANCE ? 'Hire' : score >= T_CONSIDER ? 'Consider' : 'Reject'; }
  let finalHr = String(a.overall_job_fit_narrative || '').trim();
  let summary = String(a.summary || '').trim();
  if (status === 'insufficient_data') { const note = 'NOTE: Insufficient interview evidence for a reliable score. Recommend a re-interview before deciding.'; finalHr = finalHr ? (finalHr + '\n\n' + note) : note; summary = summary ? (summary + '\n\n' + note) : note; }
  out.push({ json: { overall_score: score, recommendation, status, not_assessed: notAssessed, ratings, assessment_detail: { evidence, overrides }, summary, strengths: toArray(a.strengths), weaknesses: toArray(a.weaknesses), professional_attitude: String(a.professional_attitude_narrative || '').trim(), final_hr_evaluation: finalHr, role_specific_criteria: Array.isArray(a.role_specific_criteria) ? a.role_specific_criteria : [], communication: ratings.communication_skills || 'Not Assessed', language_fluency: ratings.english_fluency || 'Not Assessed', confidence: ratings.confidence_level || 'Not Assessed', problem_solving: ratings.problem_solving || 'Not Assessed', digital_skills: ratings.computer_skills || 'Not Assessed' } });
}
return out;
